"""Modular powers and totient prerequisites for toy RSA worksheets."""
from algebra_lessons import authored
from number_theory_lessons import source
from card_lessons import make_lessons

def e(w,q):return source('RSA',w,q)
SPECS=[
authored('modular-repeated-squaring','Evaluate a modular power using repeated squaring',
 'Find 4²⁹ modulo 19 using repeated squaring.','16',
 'Find four to the twenty-ninth power modulo nineteen using repeated squaring.',[
 ('BUILD POWERS OF TWO','Square the previous residue and reduce each time','4² ≡ 16; 4⁴ ≡ 16² ≡ 9 (mod 19)\n4⁸ ≡ 9² ≡ 5; 4¹⁶ ≡ 5² ≡ 6 (mod 19)',
 'Repeated squaring gives residues sixteen, nine, five, and six for exponents two, four, eight, and sixteen.'),
 ('SPLIT THE EXPONENT','Use the powers of two that sum to twenty-nine','29 = 16 + 8 + 4 + 1\n4²⁹ = 4¹⁶ × 4⁸ × 4⁴ × 4',
 'Twenty-nine is sixteen plus eight plus four plus one. Multiply the corresponding powers.'),
 ('MULTIPLY THEIR RESIDUES','Reduce intermediate products to keep numbers small','6 × 5 ≡ 11; 11 × 9 ≡ 4 (mod 19)\n4 × 4 = 16',
 'Multiply their residues. Six times five reduces to eleven. Eleven times nine reduces to four. Multiplying by the final four gives sixteen.'),
 ('CHECK THE RANGE','The result must be a residue modulo nineteen','0 ≤ 16 < 19\n4²⁹ ≡ 16 (mod 19)',
 'Sixteen lies in the required range. Repeated squaring avoids building the enormous original power.')],e(1,9),expression='4**29%19',value='16'),
authored('modular-stable-power-residues','Recognize powers that reach a fixed residue',
 'Find 10⁸ mod 20 and 6¹³ mod 15.','0 and 6',
 'Find ten to the eighth power modulo twenty, and six to the thirteenth power modulo fifteen.',[
 ('LOOK FOR A ZERO FACTOR','Once a power is divisible by the modulus, higher powers stay so','10² = 100 ≡ 0 (mod 20)\n10⁸ = (10²)⁴ ≡ 0⁴ ≡ 0 (mod 20)',
 'Ten squared is divisible by twenty. Group the eighth power into four copies of ten squared, so the remainder is zero.'),
 ('CHECK FOR A FIXED NONZERO RESIDUE','A residue can reproduce itself when multiplied by the base','6² = 36 ≡ 6 (mod 15)',
 'For the other power, six squared leaves remainder six modulo fifteen.'),
 ('PROVE THE RESIDUE STAYS FIXED','Multiplying six by the base returns six again','If 6ᵏ ≡ 6, then 6ᵏ⁺¹ ≡ 6 × 6 ≡ 6 (mod 15).',
 'Whenever a power leaves six, multiplying by another six leaves six again. The first power already has that remainder.'),
 ('APPLY TO THE GIVEN EXPONENTS','The stable behavior continues for the remaining multiplications','10⁸ mod 20 = 0\n6¹³ mod 15 = 6',
 'Therefore the requested remainders are zero and six. Establish the fixed behavior before extending it to a large exponent.')],e(1,3),equalities=[('10**8%20','0'),('6**13%15','6')]),
authored('modular-negative-one-power','Use a square congruent to negative one',
 'Find 12²⁶ modulo 29.\nGive both a signed representative\nand the least nonnegative remainder.','-1; least nonnegative remainder 28',
 'Find twelve to the twenty-sixth power modulo twenty-nine. Give a signed representative and the least nonnegative remainder.',[
 ('SQUARE AND REDUCE','A residue near the modulus may have a simpler negative form','12² = 144 = 5 × 29 − 1\n12² ≡ −1 (mod 29)',
 'Twelve squared is one less than five times twenty-nine, so it is congruent to negative one.'),
 ('GROUP INTO SQUARES','Twenty-six is twice thirteen','12²⁶ = (12²)¹³\n≡ (−1)¹³ (mod 29)',
 'Write the twenty-sixth power as the thirteenth power of the square. Replace that square by negative one.'),
 ('USE EXPONENT PARITY','An odd power of negative one is negative one','(−1)¹³ = −1',
 'Thirteen is odd, so negative one to that power is negative one.'),
 ('CONVERT TO THE REQUIRED REPRESENTATIVE','Add the modulus to get a nonnegative remainder','−1 ≡ 28 (mod 29)\nSigned representative: −1; canonical remainder: 28',
 'Add twenty-nine to get twenty-eight. Negative one and twenty-eight represent the same congruence class, but twenty-eight is the least nonnegative remainder.')],e(1,6),expression='12**26%29',value='28'),
authored('modular-fermat-power','Use Fermat’s theorem for a prime modulus',
 'Use Fermat’s Little Theorem\nto find 2³⁴ modulo 11.','5',
 'Use Fermat’s Little Theorem to find two to the thirty-fourth power modulo eleven.',[
 ('CHECK THE CONDITIONS','The modulus is prime and does not divide the base','11 is prime and gcd(2,11)=1.',
 'Eleven is prime, and two is coprime to eleven. Fermat’s theorem applies.'),
 ('USE THE THEOREM','The exponent one below the prime gives residue one','2¹⁰ ≡ 1 (mod 11)',
 'The theorem says that two to the tenth power is congruent to one modulo eleven.'),
 ('SPLIT THE LARGE EXPONENT','Separate multiples of ten from the leftover exponent','34 = 3 × 10 + 4\n2³⁴ = (2¹⁰)³ × 2⁴',
 'Thirty-four is three tens plus four. Group the power accordingly.'),
 ('REDUCE THE SMALL REMAINING POWER','Each complete block contributes one','2³⁴ ≡ 1³ × 16 ≡ 5 (mod 11)',
 'Each complete block contributes one. Two to the fourth is sixteen, whose remainder modulo eleven is five.')],e(4,3),expression='2**34%11',value='5'),
authored('totient-list-count-complement','List coprime residues and count their complement',
 'List the positive integers below 18 coprime to 18.\nFind ϕ(18) and the count not coprime to 18.','1,5,7,11,13,17; phi 6; noncoprime count 11',
 'List the positive integers below eighteen that are coprime to eighteen. Find phi of eighteen and the count that are not coprime.',[
 ('REMOVE SHARED PRIME FACTORS','Eighteen has prime factors two and three','18 = 2 × 3²\nKeep numbers not divisible by 2 or 3.',
 'Eighteen has prime factors two and three. A number is coprime to eighteen exactly when neither prime divides it.'),
 ('LIST AND COUNT','Use positive integers one through seventeen','Coprime list: 1, 5, 7, 11, 13, 17\nϕ(18) = 6',
 'The surviving integers are one, five, seven, eleven, thirteen, and seventeen. There are six, so phi is six.'),
 ('COUNT THE COMPLEMENT','There are seventeen positive integers below eighteen','Not coprime: 17 − 6 = 11',
 'There are seventeen positive integers below eighteen. Subtract the six coprime ones to get eleven that are not coprime.'),
 ('NOTICE THE EVEN COUNT','For n greater than two, coprime residues pair as a and n−a','Pairs here: (1,17), (5,13), (7,11)\nDistinct pairs show ϕ(n) is even for n > 2.',
 'Coprime residues pair as a and n minus a. For n greater than two these partners are distinct, so phi is even, not odd.')],e(2,1),expression='17-6',value='11'),
authored('totient-recover-prime-factors','Recover two prime factors from a product and its totient',
 'N is a product of two distinct primes.\nGiven N=299 and ϕ(N)=264, find them.\nAlso show the shortcut if one prime is known to be 13.','13 and 23',
 'N is a product of two distinct primes. Given N equals two hundred ninety-nine and phi equals two hundred sixty-four, find the primes. Also show the shortcut if one prime is known to be thirteen.',[
 ('EXPAND THE TOTIENT FORMULA','For distinct primes, phi is one less than each multiplied','ϕ(N)=(p−1)(q−1)=pq−p−q+1\np+q = N+1−ϕ(N)',
 'Expand the totient formula. Since p q equals N, the sum of the primes is N plus one minus phi.'),
 ('FIND THE SUM AND PRODUCT','Both conditions must hold','p+q = 299+1−264 = 36\npq = 299',
 'The prime sum is thirty-six, and the product is two hundred ninety-nine.'),
 ('IDENTIFY AND CHECK THE PAIR','Thirteen and twenty-three satisfy both conditions','13+23=36; 13×23=299\n(13−1)(23−1)=12×22=264',
 'Thirteen and twenty-three have the required sum and product. Their totient product is also two hundred sixty-four.'),
 ('USE A KNOWN PRIME DIRECTLY','One known factor avoids the sum-and-product search','If p=13: q−1=264/(13−1)=22\nq=23, N=13×23=299',
 'If thirteen is already known, divide phi by twelve to get q minus one equal to twenty-two. Thus q is twenty-three.')],e(2,10),equalities=[('13*23','299'),('12*22','264'),('299+1-264','36')]),
authored('totient-factorial-order','Distinguish a factorial inside and outside the totient',
 'Find ϕ(4!) and the remainder of ϕ(10)! modulo 7.','8; remainder 3',
 'Find phi of four factorial, and the remainder of phi of ten factorial modulo seven. In the second expression, take phi of ten before the factorial.',[
 ('READ THE PARENTHESES','For phi of four factorial, calculate the factorial first','4! = 24 = 2³ × 3\nϕ(4!) = ϕ(24)',
 'In the first expression, the factorial is inside phi. Four factorial is twenty-four, with prime factors two and three.'),
 ('APPLY THE TOTIENT FORMULA','Use each distinct prime once','ϕ(24) = 24(1−1/2)(1−1/3) = 8',
 'Apply the totient formula to twenty-four. The result is eight.'),
 ('REVERSE THE OPERATION ORDER','In the second expression, compute phi before factorial','ϕ(10) = 10(1−1/2)(1−1/5) = 4\nϕ(10)! = 4! = 24',
 'For the second expression, compute phi of ten first. It is four, whose factorial is twenty-four.'),
 ('REDUCE IF REQUESTED','Only after the specified operations, take the remainder','24 = 7 × 3 + 3\nϕ(10)! mod 7 = 3',
 'Finally, reduce twenty-four modulo seven to get three. Parentheses determine which operation happens first.')],e(3,5),equalities=[('24*(1-1/2)*(1-1/3)','8'),('10*(1-1/2)*(1-1/5)','4'),('24%7','3')]),
authored('totient-inverse-compositions','Find inverses after totient and factorial operations',
 'Find the inverses modulo 13 of\nϕ(14) and ϕ(14)!.','11 and 8',
 'Find the inverses modulo thirteen of phi of fourteen, and of phi of fourteen factorial, taking the totient before the factorial.',[
 ('EVALUATE THE TOTIENT','Fourteen is a product of the distinct primes two and seven','ϕ(14) = (2−1)(7−1) = 6',
 'Fourteen is two times seven. Its totient is one times six, which equals six.'),
 ('INVERT THE FIRST VALUE','An inverse multiplies the value to remainder one','6 × 11 = 66 = 13 × 5 + 1\nInverse of ϕ(14) modulo 13: 11',
 'Six times eleven is one more than a multiple of thirteen, so eleven is the first inverse.'),
 ('EVALUATE AND REDUCE THE FACTORIAL','Find the value to invert before seeking its inverse','ϕ(14)! = 6! = 720\n720 = 13 × 55 + 5',
 'Next compute six factorial, which is seven hundred twenty. Modulo thirteen it reduces to five.'),
 ('INVERT THE REDUCED VALUE','The inverse is for the whole evaluated expression','5 × 8 = 40 = 13 × 3 + 1\nInverse of ϕ(14)! modulo 13: 8',
 'Five times eight is one more than a multiple of thirteen. Thus eight is the inverse of the factorial expression.')],e(3,9),equalities=[('6*11%13','1'),('720%13','5'),('5*8%13','1')]),
authored('modular-euler-power','Use Euler’s theorem for a composite modulus',
 'Find 7⁵⁰ modulo 45 using Euler’s theorem.','4',
 'Find seven to the fiftieth power modulo forty-five using Euler’s theorem.',[
 ('CHECK COPRIMALITY','Euler requires the base and modulus to share only factor one','45 = 3² × 5; gcd(7,45)=1',
 'Forty-five factors as three squared times five, and neither prime divides seven. The base and modulus are coprime.'),
 ('COMPUTE THE TOTIENT','Use distinct prime factors in the totient formula','ϕ(45)=45(1−1/3)(1−1/5)=24\n7²⁴ ≡ 1 (mod 45)',
 'The totient is twenty-four. Euler’s theorem therefore makes seven to the twenty-fourth congruent to one.'),
 ('SPLIT THE EXPONENT','Remove full blocks of twenty-four','50 = 2 × 24 + 2\n7⁵⁰ = (7²⁴)² × 7²',
 'Fifty is two blocks of twenty-four plus two. Separate the power into those blocks and the remaining square.'),
 ('FINISH THE SMALL POWER','Full totient blocks contribute one','7⁵⁰ ≡ 1² × 49 ≡ 4 (mod 45)',
 'The blocks contribute one, and seven squared is forty-nine. Modulo forty-five, the remainder is four.')],e(4,5),expression='7**50%45',value='4'),
authored('modular-find-exponent-family','Find every exponent producing a specified residue',
 'Find the first seven positive integers n\nfor which 3ⁿ ≡ 5 (mod 11).','3,8,13,18,23,28,33',
 'Find the first seven positive integers n for which three to the power n is congruent to five modulo eleven.',[
 ('BUILD A COMPLETE RESIDUE CYCLE','Multiply by three and reduce modulo eleven','n: 1, 2, 3, 4, 5\n3ⁿ mod 11: 3, 9, 5, 4, 1',
 'The residues for exponents one through five are three, nine, five, four, and one.'),
 ('PROVE THE REPEAT AND LOCATE THE TARGET','The next multiplication returns to the first residue','1 × 3 ≡ 3 (mod 11)\nFive occurs only at position 3 in this cycle.',
 'Multiplying the final one by three starts the same cycle again. The target five appears only in position three.'),
 ('WRITE THE EXPONENT FAMILY','Repeat that position every five exponents','n = 3 + 5k, for integers k ≥ 0',
 'Therefore every positive solution has exponent three plus five k, with k zero or larger.'),
 ('LIST THE FIRST SEVEN','Use k from zero through six','3, 8, 13, 18, 23, 28, 33',
 'Use k from zero through six to obtain three, eight, thirteen, eighteen, twenty-three, twenty-eight, and thirty-three.')],e(4,9),equalities=[('3**3%11','5'),('3**5%11','1')]),
]
def lessons(doc):
 assert [n for n in range(1,34) if pow(3,n,11)==5]==[3,8,13,18,23,28,33]
 return make_lessons(SPECS,doc)
